-- Restrict privileged RPCs to the roles that actually use them.
-- Public token booking RPCs intentionally remain anon-callable because the possession of a high-entropy,
-- expiring candidate portal token is their authentication factor and the functions validate it server-side.
revoke execute on function public.calculate_placement_fee(uuid,numeric,numeric,numeric),public.campaign_performance(),public.client_portal_action(uuid,text,text),public.client_portal_data(),public.client_review_submission(uuid,text,text),public.create_candidate_portal_token(uuid,integer),public.create_placement_invoice(uuid,date),public.current_company_id(),public.get_candidate_portal_token(uuid),public.has_candidate_data_access(),public.is_manager(),public.manage_interview(uuid,text,timestamptz,integer,text,text),public.record_introduction_compliance(uuid,text,text,text,boolean,boolean,text),public.record_invoice_adjustment(uuid,text,numeric,text,text),public.record_invoice_payment(uuid,numeric,text,text),public.require_workspace_feature(text),public.reserve_client_submission(uuid,text,text,text),public.review_application(uuid,text,text),public.revoke_candidate_portal_token(uuid),public.signoff_screening_report(uuid),public.void_invoice(uuid,text) from public,anon;
grant execute on function public.calculate_placement_fee(uuid,numeric,numeric,numeric),public.campaign_performance(),public.client_portal_action(uuid,text,text),public.client_portal_data(),public.client_review_submission(uuid,text,text),public.create_candidate_portal_token(uuid,integer),public.create_placement_invoice(uuid,date),public.current_company_id(),public.get_candidate_portal_token(uuid),public.has_candidate_data_access(),public.is_manager(),public.manage_interview(uuid,text,timestamptz,integer,text,text),public.record_introduction_compliance(uuid,text,text,text,boolean,boolean,text),public.record_invoice_adjustment(uuid,text,numeric,text,text),public.record_invoice_payment(uuid,numeric,text,text),public.require_workspace_feature(text),public.reserve_client_submission(uuid,text,text,text),public.review_application(uuid,text,text),public.revoke_candidate_portal_token(uuid),public.signoff_screening_report(uuid),public.void_invoice(uuid,text) to authenticated;
revoke execute on function public.book_candidate_slot(text,uuid),public.public_booking_slots(text) from public,authenticated;
grant execute on function public.book_candidate_slot(text,uuid),public.public_booking_slots(text) to anon;
